/* prog22_snake_camel_convert.c
 *
 * Re‑implementation of the original binary’s functionality.
 * The program expects exactly two command‑line arguments:
 *
 *   prog22_snake_camel_convert <mode> <string>
 *
 *   <mode>   – either "to_camel" (camelCase → snake_case) or
 *              "to_snake" (snake_case → camelCase)
 *   <string> – the input string to be converted.
 *
 * If the arguments are missing or the mode is unknown the program
 * prints a short diagnostic message and exits.  The converted string
 * is printed with `puts`, exactly like the original binary.
 *
 * The original binary limited the output buffer to 1024 bytes; the
 * re‑implementation follows the same limit.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024

static char main_out[OUT_BUF_SIZE];

static void to_snake(const char *src)          /* snake_case → camelCase */
{
    size_t i = 0, out = 0;
    int   up_next = 0;                         /* set after '_' */

    while (src[i] != '\0' && out + 1 < OUT_BUF_SIZE) {
        char c = src[i];

        if (c == '_') {                         /* skip '_' and capitalize next */
            up_next = 1;
        } else {
            if (up_next) {
                c = (char)toupper((unsigned char)c);
                up_next = 0;
            }
            main_out[out++] = c;
        }
        ++i;
    }
    main_out[out] = '\0';
}

static void to_camel(const char *src)          /* camelCase → snake_case */
{
    size_t i = 0, out = 0;

    while (src[i] != '\0' && out + 1 < OUT_BUF_SIZE) {
        char c = src[i];

        if (isupper((unsigned char)c)) {
            /* prepend '_' before the lower‑cased character */
            if (out + 2 < OUT_BUF_SIZE) {      /* need space for '_' and the char */
                main_out[out++] = '_';
                c = (char)tolower((unsigned char)c);
            } else {
                /* not enough room for both characters – stop */
                break;
            }
        }
        main_out[out++] = c;
        ++i;
    }
    main_out[out] = '\0';
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    if (strcmp(argv[1], "to_camel") == 0) {
        to_camel(argv[2]);
        puts(main_out);
    } else if (strcmp(argv[1], "to_snake") == 0) {
        to_snake(argv[2]);
        puts(main_out);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
